WITH win(cycle,label,a,b) AS (VALUES (0,'ready-request',54816636797842,54816780619884),(0,'request-first',54816780619884,54816826064884),(0,'first200',54816826064884,54817026064884),(0,'first-second',54816826064884,54816856366634),(0,'second-third',54816856366634,54816937914302),(1,'ready-request',54820300119970,54820332900470),(1,'request-first',54820332900470,54820345761970),(1,'first200',54820345761970,54820545761970),(1,'first-second',54820345761970,54820358139012),(1,'second-third',54820358139012,54820383070428),(2,'ready-request',54823216261346,54823257033596),(2,'request-first',54823257033596,54823286499388),(2,'first200',54823286499388,54823486499388),(2,'first-second',54823286499388,54823296739970),(2,'second-third',54823296739970,54823310819054)) SELECT w.cycle,w.label,t.name AS thread,s.name,round((max(s.ts,w.a)-w.a)/1e6,3) AS offset_ms,round((min(s.ts+s.dur,w.b)-max(s.ts,w.a))/1e6,3) AS ms,s.depth FROM win w JOIN slice s ON s.ts<w.b AND s.ts+s.dur>w.a JOIN thread_track tt ON tt.id=s.track_id JOIN thread t USING(utid) JOIN process p USING(upid) WHERE p.pid=23055 AND (t.is_main_thread=1 OR t.name='RenderThread') ORDER BY w.cycle,w.label,s.ts;